T[9641]={"^Damage taken by the Stormbringers |cffffffffTorrential Wrath|r increased by (.-)%%%.%s*$","O dano recebido pelos Tormentasbrisa |cffffffffIra Torrencial|r aumenta em {{1}}%."}
