T[10082]={"^Hitting this target will cause an electrical conduit to pass through its nearby allies%.%s*$","Atingir este alvo faz um conduto elétrico percorrer os aliados próximos dele."}
T[10097]={"^Allies in your Updraft have (.-)%% increased haste%.%s*$","Todos seus aliados em Seu Corrente Ascendente Aérea têm um aumento de {{1}}% em aceleração."}
T[10098]={"^Allies in your Updraft have (.-)%% increased movement speed%.%s*$","Aliados em seu Corrente Ascendente Crescente têm um aumento de {{1}}% em velocidade de movimento."}
