T[10100]={"^Enemies in your Updraft have a (.-)%% increased chance to be critically struck%.%s*$","Inimigos em seu Corrente Ascendente Crescente têm uma maior {{1}}% de chance de ser atingidos criticamente."}
T[10752]={"^Damage taken from the Stormbringer increased by (.-)%%%. Movement speed reduced by (.-)%%%.\n\nStacks up to (.-) times%.%s*$","O dano recebido do Portador da Tempestade aumenta em {{1}}%. A velocidade de movimento reduz em {{2}}%.\n\nAcumula até {{3}} vezes."}
T[10753]={"^Damage taken from the Stormbringer's Thunder Orbs and Spheres of Power increased by (.-)%%%.%s*$","O dano recebido pelas Esferas de Trovão e as Esferas de Poder do Portador da Tempestade aumenta em {{1}}%."}
T[10754]={"^Recently struck by Gale%. Damage taken by |cffffffffTorrential Wrath|r increased by (.-)%% per stack%.%s*$","Você recebeu um acerto de Fôlego. O dano recebido por |cffffffffIra Torrencial|r aumenta em {{1}}% por acúmulo."}
