T[10760]={"^Whenever you cast an offensive Stormbringer spell, you have a chance to make your next Crackling Surge incur no cooldown and generate no static%.This effect can stack up to 6 times%.%s*$","Sempre que você lançar um feitiço ofensivo de Portador da Tempestade, há uma chance de fazer seu próximo Surto Crepitante não acionar recarga nem gerar Estática. Este efeito acumula até 6 vezes."}
T[10765]={"^Damage taken from the Stormbringer's Lightning Orbs increased by (.-)%%%.%s*$","O dano recebido pelas Esferas de Raio do Portador da Tempestade aumenta em {{1}}%."}
T[10986]={"^Your next Call Lightning, Arm of Thorim, Crackling Surge, Thunderstrike, Lightning Whip or Stormforge Blast will deal (.-)%% increased damage, have (.-)%% reduced Cooldown, but (.-)%% increased Cast Time%.\n\nStacks up to 20 times%.%s*$","Seu próximo Invocar Relâmpago, Braço de Thorim, Surto Crepitante, Golpe de Trovão, Chicote de Relâmpago ou Explosão da Forja da Tempestade causará {{1}}% a mais de dano e terá {{2}}% menos recarga, mas seu tempo de lançamento aumentará em {{3}}%.\n\nAcumula até 20 vezes."}
T[10990]={"^Healing for (.-) every (.-) sec%.\n\nMelee Attack Speed, Ranged Attack Speed, and Spell Haste increased by (.-)%%%.%s*$","Cura em {{1}} a cada {{2}} s.\n\nAumenta a velocidade de ataque corpo a corpo, a velocidade de ataque à distância e a aceleração com feitiços em {{3}}%."}
T[11037]={"^Call Lightning damage increased by (.-)%%%s*$","Dano de Labareda chamada aumenta em {{1}}%"}
T[11090]={"^(.-)%% of single target Nature Damage dealt by the Stormbringer to enemies within (.-) yd of you is also dealt to you%.\n\nDamage increased based on stacks%.%s*$","{{1}}% do dano de Natureza causado pelo Portador da Tempestade a alvos em um raio de {{2}} m de você também te é causado.\n\nO dano aumenta conforme os acúmulos."}
T[11465]={"^Your next Storm Alert or Torrential Wrath is instant cast%.%s*$","Seu próximo Alerta de Tempestade ou Fúria torrencial é instantâneo."}
T[11907]={"^Increases the chance to trigger Lightning Overload by (.-)%% and reduces the cast time of your next Lightning Bolt or Chain Lightning by (.-)%%%. In addition, the damage of your next Electrocute is increased by (.-)%% %((.-)%% against players%)%.%s*$","Aumenta a chance de ativar Sobrecarga elétrica em {{1}}% e reduz o tempo de lançamento de seu próximo Relâmpago ou Cadeia relâmpago em {{2}}%. Além disso, o dano de seu próximo Eletrocutar aumenta em {{3}}% ({{4}}% contra jogadores)."}
T[11958]={"^Your non%-periodic damaging abilities and spells have a chance to strike your target's location with lightning, dealing Nature damage to the target and leaving an electrified area slowing enemies by 25%% and dealing damage every second for 4 seconds%.%s*$","Suas habilidades e feitiços de dano não periódico têm chance de atingir a localização do alvo com um relâmpago, causando dano de Natureza ao alvo e deixando uma área eletrificada que reduz em 25% a velocidade dos inimigos e causa dano a cada segundo durante 4 s."}
T[13833]={"^This creature seems to brim with natural energies, killing this creature will redirect this pent up energy towards you and your party, dealing |cffFF9900(.-)|r Nature damage every |cffFF9900(.-)|r seconds to nearby allies%.%s*$","Esta criatura parece transbordar de energias naturais. Matá-la redireciona toda a energia acumulada para você e seu grupo, causando |cffFF9900{{1}}|r de dano de Natureza a aliados próximos a cada |cffFF9900{{2}}|r segundos."}
T[13837]={"^Your Thunderstorm grows in intensity, \nincreasing the damage and mana gain by (.-)%%, but increases the cast time by 2 seconds%.%s*$","Sua Trovoada aumenta de intensidade, elevando em {{1}}% o dano e o ganho de mana, mas aumentando o tempo de lançamento em 2 s."}
