T[14917]={"^%$%?s707615|s560020%[%]%[|cFFFFFFFFCall Lightning|r%]%$%?s707615%[|cFFFFFFFFAeroblast|r%]%[%]%$%?s560020%[|cFFFFFFFFTorrential Wrath|r%]%[%] cleaves multiple enemies%. \n\nCritical strikes deal bonus damage and grant stacking spell haste%. \n\nGenerates 5 Static every (.-) sec%.%s*$","$?s707615|s560020[][|cFFFFFFFFInvocar Relâmpago|r]$?s707615[|cFFFFFFFFExplosão Aérea|r][]$?s560020[|cFFFFFFFFIra Torrencial|r][] atinge vários inimigos.\n\nAcertos críticos causam dano adicional e concedem aceleração com feitiços acumulável.\n\nGera 5 de Estática a cada {{1}} s."}
T[14919]={"^Grants direct Nature Damage dealt an 8%-16%% chance to make your next |cffffffffCrackling Surge|r instant, incur no cooldown, and generate 50%% less Static%. Stacks (.-) times%. Each use consumes a stack%.\n\nChance based on |cffcc99ffStatic|r level%.%s*$","Concede ao dano direto de Natureza de 8% a 16% de chance de fazer seu próximo |cffffffffSurto Crepitante|r ser instantâneo, não acionar recarga e gerar 50% menos Estática. Acumula {{1}} vezes. Cada uso consome um acúmulo.\n\nA chance depende do nível de |cffcc99ffEstática|r."}
T[14935]={"^|cffffffffCrackling Surge|r and |cffffffffElectrocute|r add 2 stacks of |cffffffffFlux|r to the target and allows both spells to strike an additional nearby enemy%.%s*$","|cffffffffSurto Crepitante|r e |cffffffffEletrocutar|r Adicionem 2 acúmulos de |cffffffffFluxo|r o alvo e permitem que ambos feitiços atinjam a um inimigo próximo adicional."}
T[15034]={"^Increases the damage of your next |cffffffffAeroblast|r and Electrocute by (.-)%%, stacking (.-) times%.%s*$","Aumenta o dano de seu próximo |cffffffffExplosão Aérea|r e Eletrocutar em {{1}}%, acumulando-se {{2}} vezes."}
T[15035]={"^Increases the damage of your next |cffffffffCall Lightning|r and Electrocute by (.-)%%, stacking (.-) times%.%s*$","Aumenta o dano de seu próximo |cffffffffInvocar Relâmpago|r e Eletrocutar em {{1}}%, acumulando-se {{2}} vezes."}
T[15052]={"^You can use Electrocute regardless of your target's current health and generates 10 additional Static%.%s*$","Você pode usar Eletrocutar independentemente de a vida atual de seu alvo e gera 10 Estática adicional."}
T[15428]={"^Cloudburst%s*$","Explosão de Nuvem"}
T[15789]={"^Felmyst drenches the area she flies over in a higly necrotic vapor, inflicting lethal Shadow damage to all enemies she passes over, ressurecting undead burried beneath the ground and asphyxiates all enemies in the area, inflicting additional Shadow damage every second for (.-) to all surviving enemies inside, preventing all actions and healing and restores the health of all undead inside of it%.%s*$","Felmyst cobre a área sobre a qual voa com um vapor altamente necrótico, causando dano letal de Sombra aos inimigos por quem passa, ressuscitando os mortos-vivos enterrados e asfixiando todos os inimigos na área. Os sobreviventes dentro do vapor sofrem dano adicional de Sombra a cada segundo durante {{1}}, não podem realizar ações nem receber cura, e todos os mortos-vivos na área têm a vida restaurada."}
